@tool
async def vault_search(query: str, limit: int = 20) -> str:
    """Search the user's Obsidian vault by note title/text; returns vault-relative paths and matching lines."""
    r = await getattr(tool, "omp-ui_vault_search")({"i": "Searching vault", "query": query, "limit": limit})
    return str(r)

@tool
async def vault_read(path: str) -> str:
    """Read one vault note by vault-relative path or bare title."""
    r = await getattr(tool, "omp-ui_vault_read")({"i": "Reading vault note", "path": path})
    return str(r)

@tool
async def vault_write(title: str, content: str, tags: list[str] = None) -> str:
    """Create a note omp-ui/<title>.md in the vault. Plain markdown body, no frontmatter."""
    r = await getattr(tool, "omp-ui_vault_write")({"i": "Writing vault note", "mode": "create", "title": title, "content": content, "tags": tags})
    return str(r)

